  function BetterQoL.combo_partners.row(k, e, focused, current)
    local L, R = BetterQoL.combo_partners.ITEM, BetterQoL.combo_partners.R
    for _, m in ipairs(R.HIDE) do
      funcLuaMenuCommand(3405944500, L, m, false, k)
    end
