        BetterQoL.combo_partners.return_hidden = false
        VRFW.host.menu_command(711242136 --[[CMND_SET_LAYER_VISIBLE]], L, 0, true)
      end
      return
    end
    if BetterQoL.combo_partners.return_hidden then
      return
    end
    local exists = VRFW.host.menu_command(262659071 --[[CMND_IS_EXIST_LAYER]], L)
    if not (exists == true) then
      return
    end
    local visible = VRFW.host.menu_command(1262717583 --[[CMND_IS_LAYER_VISIBLE]], L, 0)
    if visible == true then
      BetterQoL.combo_partners.return_hidden = true
      VRFW.host.menu_command(711242136 --[[CMND_SET_LAYER_VISIBLE]], L, 0, false)
    end
  end

