    VRFW.param.clear(G.N)
    for i = 1, 4 do
      VRFW.param.clear(G.H[i])
      VRFW.param.clear(G.I[i])
    end
  end

  -- the squad handle of slot k's named partner (the engine's own pick for that slot), 0 = none or not in the squad
  function BetterQoL.combo_partners.named_default(list, info, k)
    local c = info.named[k]
    if c ~= nil then
      for _, e in ipairs(list) do
        if e.hdl ~= 0 and e.chara == c then
          return e.hdl
        end
      end
    end
    return 0
  end

  -- Returns the performers in cast order.
  function BetterQoL.combo_partners.performers(player, list, picks, info)
    local function entry(h)
      for _, e in ipairs(list) do
        if h ~= 0 and e.hdl == h then
          return e
        end
      end
      if h ~= 0 then
        return BetterQoL.combo_partners.entry(h)
      end
      return {hdl = 0}
    end
    local out = {entry(player)}
    for k = 1, info.slots do
      local h = picks[k] or 0
      if h == 0 then
        h = BetterQoL.combo_partners.named_default(list, info, k)
      end
      out[#out + 1] = entry(h)
    end
    return out
  end

  function BetterQoL.combo_partners.confirm(screen, player, list, picks, info, mname)
    local s = BetterQoL.combo_partners.text(BetterQoL.combo_partners.TX_ASK, mname)
    local perf = BetterQoL.combo_partners.performers(player, list, picks, info)
    local G = BetterQoL.combo_partners.GW
    BetterQoL.combo_partners.gw_clear()
    local m = math.min(#perf, 4)
    local names = {}
    for i = 1, m do
      local e = perf[i]
      local el = (e.chara ~= nil and e.chara ~= 0 and type(e.element) == "number" and BetterQoL.combo_partners.ELEM_SPR[e.element] ~= nil) and e.element or 0
      local ps = (type(e.pos) == "number" and e.pos >= 0 and e.pos <= 3) and e.pos + 1 or 0
      VRFW.param.set(G.H[i], e.hdl or 0)
      VRFW.param.set(G.I[i], el * 10 + ps)
      names[#names + 1] = string.format("%08X", BetterQoL.combo_partners.U32(e.hdl or 0))
    end
    VRFW.param.set(G.N, m)
    BetterQoL.combo_partners.log("confirm", m, "cards", table.concat(names, " "))
    BetterQoL.combo_partners.help(screen, BetterQoL.combo_partners.TX_HELP_CONFIRM)
    BetterQoL.combo_partners.guide(screen, {{BetterQoL.combo_partners.TX_ACCEPT, BetterQoL.combo_partners.GL_ENTER, BetterQoL.combo_partners.K_ENTER}, {BetterQoL.combo_partners.TX_BACK, BetterQoL.combo_partners.GL_BACK, BetterQoL.combo_partners.K_BACK}})
    local yes = VRFW.question.ask(s, {window = G.WINDOW, object = BetterQoL.combo_partners.U32(perf[1].hdl or 0)})
    if VRFW.param.has(G.N) then
      BetterQoL.combo_partners.log("confirm: general_window did not take the cards (BetterQoL's betterqol_cp_gw hook missing)")
    end
    BetterQoL.combo_partners.gw_clear()
    return yes
  end

  function BetterQoL.combo_partners.preview(screen, picks, slot, hdl)
    if screen.preview == nil then
      return
    end
    local preview = {}
    for k, h in pairs(picks) do
      preview[k] = h
    end
    preview[slot] = hdl or 0
    pcall(screen.preview, preview)
  end

  -- Draws one page.
  function BetterQoL.combo_partners.page(screen, list, picks, slot, info)
    for _, e in ipairs(list) do
      e.taken = false
      if e.hdl ~= 0 then
        for k = 1, info.slots do
          if k ~= slot and picks[k] == e.hdl then
            e.taken = true
          end
        end
      end
    end
    local cur = picks[slot] or 0
    local sel = 0
    for i, e in ipairs(list) do
      if e.hdl == cur then
        sel = i - 1
      end
    end
    local first = math.max(0, math.min(sel, #list - BetterQoL.combo_partners.VIEW))
    BetterQoL.combo_partners.list_show(screen, true, list, first, sel, cur)
    BetterQoL.combo_partners.preview(screen, picks, slot, list[sel + 1].hdl)
    BetterQoL.combo_partners.help(screen, BetterQoL.combo_partners.TX_HELP_PICK)
    BetterQoL.combo_partners.guide(screen, {{BetterQoL.combo_partners.TX_ACCEPT, BetterQoL.combo_partners.GL_ENTER, BetterQoL.combo_partners.K_ENTER}, {BetterQoL.combo_partners.TX_BACK, BetterQoL.combo_partners.GL_BACK, BetterQoL.combo_partners.K_BACK}})
    coroutine.yield()
    while true do
      coroutine.yield()
      if screen.frame ~= nil then
        pcall(screen.frame)
      end
      local moved = false
      if BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_BACK) then
        BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_BACK)
        return nil
      elseif BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_ENTER) or BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_CLICK) then
        if list[sel + 1].taken then
          BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_NG)
        else
          BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_DECIDE)
          return sel
        end
      elseif BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_DOWN) and sel < #list - 1 then
        sel = sel + 1
        if sel >= first + BetterQoL.combo_partners.VIEW then
          first = first + 1
        end
        moved = true
      elseif BetterQoL.combo_partners.key(BetterQoL.combo_partners.K_UP) and sel > 0 then
        sel = sel - 1
        if sel < first then
          first = first - 1
        end
        moved = true
      end
      if moved then
        BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_MOVE)
        BetterQoL.combo_partners.list_show(screen, true, list, first, sel, cur)
        BetterQoL.combo_partners.preview(screen, picks, slot, list[sel + 1].hdl)
      end
    end
  end

  function BetterQoL.combo_partners.open(screen, skill, info)
    local message = screen.message or BetterQoL.combo_partners.message
    local mname = BetterQoL.combo_partners.move_name(skill)
    local player = screen.player
    if player == nil or player == 0 then
      BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_NG)
      BetterQoL.combo_partners.log("open refused: no player known", string.format("skill %08X", skill))
      return
    end
    if info.slots <= 0 then
      BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_NG)
      return
    end
    local list = BetterQoL.combo_partners.candidates(screen, info)
    if list == nil then
      -- Handles being opened without a squad (story field, a scout).
      BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_NG)
      message(BetterQoL.combo_partners.text(BetterQoL.combo_partners.TX_NOTEAM))
      return
    end
    BetterQoL.combo_partners.SE(BetterQoL.combo_partners.SE_DECIDE)
    screen.begin()
    BetterQoL.combo_partners.picking = true
    local done, err = pcall(function()
      local saved = BetterQoL.combo_partners.get(player, skill)
      local picks = {}
      for k = 1, info.slots do
        -- Handles a named slot with no saved pick.
        picks[k] = saved[k] or 0
        if picks[k] == 0 then
          picks[k] = BetterQoL.combo_partners.named_default(list, info, k)
        end
      end
      local initial = {}
      for k = 1, info.slots do
        initial[k] = picks[k]
      end
      BetterQoL.combo_partners.log("open", string.format("player %08X skill %08X performers %d slots %d named %d team %d", player, skill,
        info.performers, info.slots, #info.named, #list - 1))
      local slot = 1
      while slot >= 1 and slot <= info.slots do
        local i = BetterQoL.combo_partners.page(screen, list, picks, slot, info)
        if i == nil then
          slot = slot - 1
        else
          picks[slot] = list[i + 1].hdl
          slot = slot + 1
        end
      end
      pcall(BetterQoL.combo_partners.list_show, screen, false, {}, 0, 0, 0)
      if slot > info.slots then
        local same = true
        for k = 1, info.slots do
          if (picks[k] or 0) ~= (initial[k] or 0) then
            same = false
          end
        end
        if same then
          BetterQoL.combo_partners.log("unchanged", string.format("skill %08X", skill))
        elseif BetterQoL.combo_partners.confirm(screen, player, list, picks, info, mname) then
          local r = VRFW.host.command(BetterQoL.combo_partners.CMD_SET, player, skill, picks[1] or 0, picks[2] or 0, picks[3] or 0)
          BetterQoL.combo_partners.SE((r == true) and BetterQoL.combo_partners.SE_OK or BetterQoL.combo_partners.SE_NG)
          BetterQoL.combo_partners.log("saved", string.format("player %08X skill %08X -> %08X %08X %08X (%s)", player, skill,
            picks[1] or 0, picks[2] or 0, picks[3] or 0, tostring(r)))
        else
          BetterQoL.combo_partners.log("cancelled at confirm", string.format("skill %08X", skill))
        end
      else
        BetterQoL.combo_partners.log("cancelled", string.format("skill %08X", skill))
      end
    end)
    pcall(BetterQoL.combo_partners.list_show, screen, false, {}, 0, 0, 0)
    pcall(BetterQoL.combo_partners.return_guide, true)
    coroutine.yield()
    BetterQoL.combo_partners.picking = false
    screen.finish()
    if not done then
      BetterQoL.combo_partners.log("picker error", tostring(err))
    end
  end
  -- ===== end of the shared partner picker =====

