  function BetterQoL.combo_partners.skill_table(host, ctx)
    local locals = host.L
    local state = {row = ctx.row}
    local skill = BetterQoL.combo_partners.U32(ctx.move)
    local function cover(show)
      local screen_helpers = locals.PL
      if type(screen_helpers) == "table" and type(screen_helpers.list_cover) == "function" then
        pcall(screen_helpers.list_cover, show)
      end
    end
    local function refocus()
      local rows = locals.L_ROW
      if rows == nil or state.row == nil then
        return
      end
      local ok, at = pcall(funcLuaMenuCommand, BetterQoL.combo_partners.FOCUS_INDEX, rows)
      if not ok or at ~= state.row then
        pcall(funcLuaMenuCommand, BetterQoL.combo_partners.FOCUS_SET, rows, state.row, true)
      end
    end
    local function help(text)
      pcall(funcLuaMenuCommand, 1083631230 --[[CMND_SET_MENU_TEXT_STRING]], BetterQoL.combo_partners.HELP_LINE, BetterQoL.combo_partners.HELP_TEXT, text, 0)
    end
    return {
      player = BetterQoL.combo_partners.U32(ctx.chara),
      backdrop = false, -- the screen's list cover draws the blue backdrop
      members = function()
        return BetterQoL.combo_partners.skill_table_members(locals)
      end,
      begin = function()
        cover(true)
        BetterQoL.combo_partners.skill_table_column(locals, false)
        BetterQoL.combo_partners.skill_table_switcher(locals, false)
        refocus()
      end,
      frame = refocus,
      help = help,
      preview = function(picks)
        BetterQoL.combo_partners.CARD_FACES.preview = {skill = skill, picks = picks}
        local ok, err = pcall(BetterQoL.combo_partners.card_faces_for, skill)
        if not ok then
          BetterQoL.combo_partners.log("card faces preview failed", tostring(err))
        end
      end,
      finish = function()
        cover(false)
        BetterQoL.combo_partners.skill_table_column(locals, true)
        BetterQoL.combo_partners.skill_table_switcher(locals, true)
        refocus()
        BetterQoL.combo_partners.CARD_FACES.preview = nil
        pcall(BetterQoL.combo_partners.card_faces_for, skill)
        if type(locals.GUIDE_TEXT) == "string" then
          help(locals.GUIDE_TEXT) -- the screen's own help line back
        end
        if type(UpdateEquipItemInfo) == "function" then
          pcall(UpdateEquipItemInfo) -- the row's own guide and panel back
        end
      end,
      guide_menu = function()
        return locals.n12
      end,
    }
  end

