  function BetterQoL.combo_partners.card_faces_for(skill)
    local F = BetterQoL.combo_partners.CARD_FACES
    local host = BetterQoL.combo_partners.skill_table_host()
    skill = BetterQoL.combo_partners.U32(skill)
    if host == nil or skill == 0 or not BetterQoL.combo_partners.card_faces_layer_exists() or not BetterQoL.combo_partners.card_faces_wanted(host) then
      BetterQoL.combo_partners.card_faces_clear()
      return
    end
    local info = BetterQoL.combo_partners.combo_info(skill)
    local player = BetterQoL.combo_partners.U32(host.L.n)
    if info == nil or player == 0 then
      BetterQoL.combo_partners.card_faces_clear()
      return
    end
    local squad = {}
    for _, m in ipairs(BetterQoL.combo_partners.skill_table_members(host.L) or {}) do
      local h = BetterQoL.combo_partners.U32(m.hdl)
      local ok, chara = pcall(funcLuaCommand, 1131797651, h, 1)
      squad[#squad + 1] = {hdl = h, chara = ok and BetterQoL.combo_partners.U32(chara) or 0}
    end
    local preview = F.preview
    local picks = (preview ~= nil and preview.skill == skill) and preview.picks or BetterQoL.combo_partners.get(player, skill)
    local performers = BetterQoL.combo_partners.performers(player, squad, picks, info)
    local parts = {string.format("%08X", skill)}
    for _, e in ipairs(performers) do
      parts[#parts + 1] = string.format("%08X", BetterQoL.combo_partners.U32(e.chara or 0))
    end
    local key = table.concat(parts, " ")
    if F.want ~= nil and F.want_key == key then
      return
    end
    F.want, F.want_key = performers, key
    F.want_gen = F.want_gen + 1
  end

  function BetterQoL.combo_partners.card_face_fill(i, e)
    local F, R = BetterQoL.combo_partners.CARD_FACES, BetterQoL.combo_partners.R
    local L = F.LAYER
    for _, m in ipairs(F.ROW_MESHES) do
      pcall(funcLuaMenuCommand, 3405944500 --[[CMND_SET_MESH_VISIBLE]], L, m, false, i)
    end
    for _, q in ipairs(F.ROW_LOCATORS) do
      pcall(funcLuaMenuCommand, 2158717427 --[[locator visible]], L, q, false, i)
    end
    for _, num in ipairs(F.ROW_NUMBERS) do
      pcall(funcLuaMenuCommand, 1233047821 --[[number visible]], L, i, num, false)
    end
    for _, t in ipairs(F.ROW_TEXTS) do
      pcall(funcLuaMenuCommand, 2735666188 --[[text visible]], L, t, false, i)
    end
    local face = BetterQoL.combo_partners.face(L, i, e, R.FACE, R.FACE_SLOT)
    BetterQoL.combo_partners.place(L, i, F.PLATE_MESH, F.PLATE_FRAME)
    pcall(funcLuaMenuCommand, 558735651, L, F.PLATE_TEXTURE, F.PLATE_SPRITE, F.PLATE_SLOT, 0, i)
    pcall(funcLuaMenuCommand, 3405944500, L, F.PLATE_MESH, true, i)
    return face
  end

  function BetterQoL.combo_partners.card_faces_origin(host)
    local F = BetterQoL.combo_partners.CARD_FACES
    local x, y = F.DEFAULT_X, F.DEFAULT_Y
    local screen_helpers = host.L.PL
    if type(screen_helpers) == "table" and type(screen_helpers.layout_loc) == "function" then
      local ok, lx, ly = pcall(screen_helpers.layout_loc, F.BADGE_LOCATOR)
      if ok and type(lx) == "number" and type(ly) == "number" then
        x, y = lx, ly
      end
    end
    local okb, visible = pcall(funcLuaMenuCommand, 1262717583 --[[CMND_IS_LAYER_VISIBLE]], host.L.L_DETAIL_LV, 0)
    local has_badge = okb and visible == true
    if not has_badge then
      x = x - F.BADGE_SPAN
    end
    return x, y, has_badge
  end

  function BetterQoL.combo_partners.card_faces_draw(host)
    local F = BetterQoL.combo_partners.CARD_FACES
    local performers = F.want
    if performers == nil or not BetterQoL.combo_partners.card_faces_layer_exists() then
      return
    end
    local count = math.min(#performers, F.COUNT)
    local okl, loading = pcall(funcLuaMenuCommand, 3057768039 --[[CMND_IS_LOADING]], F.LAYER)
    local ready = not (okl and loading == true)
    local x0, y0, has_badge = BetterQoL.combo_partners.card_faces_origin(host)
    local scale = F.SIZE / F.FACE_WIDTH
    local drawn = {}
    for i = 0, F.COUNT - 1 do
      local e = i < count and performers[i + 1] or nil
      local open = BetterQoL.combo_partners.card_face_is_open(i)
      if e ~= nil and not open then
        local asked = F.open_requests[i]
        if asked == nil or asked >= F.OPEN_RETRY then
          F.open_requests[i] = 0
          F.drawn_gen[i] = nil
          BetterQoL.combo_partners.face_forget(F.LAYER, i)
          pcall(funcLuaMenuCommand, 629267548 --[[CMND_OPEN_LAYER]], F.LAYER, i)
          pcall(funcLuaMenuCommand, BetterQoL.combo_partners.LAYER_VISIBLE, F.LAYER, i, false)
        else
          F.open_requests[i] = asked + 1
        end
        drawn[#drawn + 1] = "opening"
      elseif e ~= nil and ready then
        F.open_requests[i] = nil
        local cx = x0 + F.GAP + F.SIZE / 2 + i * (F.SIZE + F.SPACE)
        local okp = pcall(funcLuaMenuCommand, 1389957207 --[[CMND_SET_LAYER_LOCAL_POS]], F.LAYER, cx,
          y0 - F.FACE_CENTRE_Y * scale, 0, i)
        pcall(funcLuaMenuCommand, 3778714801 --[[CMND_SET_LAYER_LOCAL_SCALE]], F.LAYER, scale, scale, 1, i)
        if F.drawn_gen[i] ~= F.want_gen then
          local okf, face = pcall(BetterQoL.combo_partners.card_face_fill, i, e)
          F.drawn_gen[i] = okf and F.want_gen or nil
          e.face_drawn = okf and face
        end
        local up = okp and F.drawn_gen[i] == F.want_gen
        pcall(funcLuaMenuCommand, BetterQoL.combo_partners.LAYER_VISIBLE, F.LAYER, i, up)
        drawn[#drawn + 1] = up and string.format("%08X%s", BetterQoL.combo_partners.U32(e.hdl or 0), e.face_drawn and "" or "?")
          or "setup"
      elseif open then
        pcall(funcLuaMenuCommand, BetterQoL.combo_partners.LAYER_VISIBLE, F.LAYER, i, false)
      end
    end
    F.shown = true
    local key = table.concat(drawn, " ")
    if key ~= F.logged then
      F.logged = key
      BetterQoL.combo_partners.log("card faces", key, "at", x0, y0, has_badge and "after the level badge" or "after IA activada")
    end
  end

  function BetterQoL.combo_partners.card_faces_step()
    local F = BetterQoL.combo_partners.CARD_FACES
    local host = BetterQoL.combo_partners.skill_table_host()
    if host == nil then
      return
    end
    if BetterQoL.combo_partners.skill_table_gone(host) then
      BetterQoL.combo_partners.card_faces_shut()
    elseif F.want ~= nil and BetterQoL.combo_partners.card_faces_wanted(host) then
      BetterQoL.combo_partners.card_faces_draw(host)
    else
      BetterQoL.combo_partners.card_faces_hide()
    end
  end

  BetterQoL = type(BetterQoL) == "table" and BetterQoL or {}

  -- the x_action entry of Character Reforged's skill table host (see the top of this file)
  function BetterQoL.skill_table_partners(phase, ctx)
    local host = BetterQoL.combo_partners.skill_table_host()
    if host == nil or type(ctx) ~= "table" then
      return nil
    end
    if phase == "available" then
      return type(ctx.row) == "number" and (ctx.move or 0) ~= 0 and BetterQoL.combo_partners.combo_info(ctx.move) ~= nil
    elseif phase == "guide" then
      return true
    elseif phase ~= "press" then
      return nil
    end
    local skill = BetterQoL.combo_partners.U32(ctx.move)
    local info = BetterQoL.combo_partners.combo_info(skill)
    if info == nil then
      host.sound("refused")
      return
    end
    BetterQoL.combo_partners.open(BetterQoL.combo_partners.skill_table(host, ctx), skill, info)
  end

  function BetterQoL.combo_partners.wrap_skill_table_global(name, make, owner)
    BetterQoL.combo_partners.wrap_global(name, make, "skill_table_wrapped", owner)
  end

  BetterQoL.combo_partners.wrap_skill_table_global("OnSetupLayer", function(previous)
    return function(a1, a2, ...)
      if BetterQoL.combo_partners.ours(a1) then
        BetterQoL.combo_partners.setup_layer(a1, a2, BetterQoL.combo_partners.SKILL_TABLE_PRIO)
        return
      end
      if a1 == BetterQoL.combo_partners.CARD_FACES.LAYER then
        -- Draws the move card's performer faces.
        local r = table.pack(previous(a1, a2, ...))
        pcall(funcLuaMenuCommand, 1491630496 --[[CMND_SET_DRAW_PRIORITY]], a1, a2, BetterQoL.combo_partners.CARD_FACES.PRIORITY, true)
        pcall(funcLuaMenuCommand, BetterQoL.combo_partners.LAYER_VISIBLE, a1, a2, false)
        return table.unpack(r, 1, r.n)
      end
      return previous(a1, a2, ...)
    end
  end)

  BetterQoL.combo_partners.wrap_skill_table_global("OnOpenLayer", function(previous)
    return function(a1, a2, ...)
      if BetterQoL.combo_partners.ours(a1) then
        if not BetterQoL.combo_partners.picking then
          pcall(funcLuaMenuCommand, 711242136, a1, a2, false)
        end
        return
      end
      if a1 == BetterQoL.combo_partners.CARD_FACES.LAYER then
        -- The engine runs this inside CMND_OPEN_LAYER.
        local r = table.pack(previous(a1, a2, ...))
        pcall(funcLuaMenuCommand, BetterQoL.combo_partners.LAYER_VISIBLE, a1, a2, false)
        if type(a2) == "number" then
          BetterQoL.combo_partners.CARD_FACES.drawn_gen[a2] = nil
        end
        return table.unpack(r, 1, r.n)
      end
      return previous(a1, a2, ...)
    end
  end)

  -- Runs while a page is up.
  BetterQoL.combo_partners.wrap_skill_table_global("OnChangeFocus", function(previous)
    return function(a1, a2, ...)
      if BetterQoL.combo_partners.picking then
        return
      end
      return previous(a1, a2, ...)
    end
  end)

  -- Shows the move card's performers.
  BetterQoL.combo_partners.wrap_skill_table_global("skill_table_detail_show", function(previous)
    return function(skill, row, ...)
      local r = table.pack(previous(skill, row, ...))
      local ok, err = pcall(BetterQoL.combo_partners.card_faces_for, r[1] == true and skill or 0)
      if not ok then
        BetterQoL.combo_partners.log("card faces failed", tostring(err))
      end
      return table.unpack(r, 1, r.n)
    end
  end, CharacterReforged)

  BetterQoL.combo_partners.wrap_skill_table_global("Step", function(previous)
    return function(...)
      local r = table.pack(previous(...))
      local F = BetterQoL.combo_partners.CARD_FACES
      if F.want ~= nil or F.shown then
        local ok, err = pcall(BetterQoL.combo_partners.card_faces_step)
        if not ok then
          BetterQoL.combo_partners.log("card faces step failed", tostring(err))
        end
      end
      return table.unpack(r, 1, r.n)
    end
  end)

  BetterQoL.combo_partners.wrap_skill_table_global("OnBack", function(previous)
    return function(...)
      local r = table.pack(previous(...))
      if BetterQoL.combo_partners.skill_table_gone(BetterQoL.combo_partners.skill_table_host()) then
        pcall(BetterQoL.combo_partners.card_faces_shut)
      end
      return table.unpack(r, 1, r.n)
    end
  end)
end
